import csv, sys
from collections import Counter
sys.stdout.reconfigure(encoding='utf-8')
BASE = r'C:\Users\eric_rash\Desktop\DEV\Flint\.claude\worktrees\step1-triage\data\jev_pass'
inp = list(csv.DictReader(open(BASE + r'\label_input.csv', encoding='utf-8')))
out = list(csv.DictReader(open(BASE + r'\jev_01_draft.csv', encoding='utf-8')))
DISC = {'Strength and power','Periodization and programming','Speed and sprint','Conditioning and energy systems',
'Rehab and return to play','Injury risk and prevention','Load monitoring and GPS','Testing and assessment',
'Recovery and sleep','Nutrition and body composition','Anatomy, physiology and biomechanics',
'Coaching, skill acquisition and constraints-led approach','Data, technology and reporting',
'Leadership, culture and psychology','Female athlete','Youth and development'}
ROUTES = {'skip','already in Zotero','paper to Zotero','book','atomize','transcribe','catalog only'}
errs = []
ik = [x['key'] for x in inp]; ok = [x['key'] for x in out]
if len(out) != len(inp): errs.append('rowcount')
if sorted(ik) != sorted(ok) or len(set(ok)) != len(ok): errs.append('keys')
for x in out:
    for d in filter(None, x['disciplines'].split(';')):
        if d not in DISC: errs.append(('disc', x['key'], d))
    if x['tier'] not in ('B', 'C'): errs.append(('tier', x['key']))
    if x['route'] not in ROUTES: errs.append(('route', x['key']))
    if x['candidate'] not in ('yes', 'no'): errs.append(('cand', x['key']))
    if x['route'] == 'skip' and x['tier'] != 'C': errs.append(('skipB', x['key']))
    if x['tier'] == 'C' and x['route'] != 'skip': errs.append(('Cnotskip', x['key']))
    if '\u2014' in x['reason'] or '\u2013' in x['reason'] or not x['reason']: errs.append(('reason', x['key']))
print('errors', errs)
print('rows', len(out))
print('tier', Counter(x['tier'] for x in out))
print('route', Counter(x['route'] for x in out))
print('candidates', sum(x['candidate'] == 'yes' for x in out))
bykey = {x['key']: x for x in inp}
for x in out:
    if x['candidate'] == 'yes':
        print('  YES', bykey[x['key']]['path'], '|', x['reason'])
JMAP = {'a research paper': {'paper to Zotero', 'already in Zotero'}, 'a book or book chapter': {'book'},
 'course or lecture material': {'atomize', 'transcribe'},
 'a coaching resource (programs, drills, templates, presentations)': {'atomize', 'catalog only'},
 "Eric's own work": {'catalog only', 'skip'}, 'not sport-science material': {'skip'}}
rd = dd = either = 0
for x in out:
    j = bykey[x['key']]
    a = x['route'] not in JMAP[j['jev_route']]
    b = set(filter(None, x['disciplines'].split(';'))) != set(filter(None, j['jev_disciplines'].split(';')))
    rd += a; dd += b; either += (a or b)
print('route disagree', rd, 'disciplines disagree', dd, 'either', either)
print('route disagree breakdown', Counter((bykey[x['key']]['jev_route'][:25], x['route']) for x in out if x['route'] not in JMAP[bykey[x['key']]['jev_route']]))

